{
  "SqlCode": "purch_lines",
  "SqlName": "Xaridlar qatorlari bilan",
  "SqlText": "SELECT T0.DocNum, T0.DocDate, T0.CardCode, T1.ItemCode, T1.Quantity, T1.Price FROM OPCH T0 INNER JOIN PCH1 T1 ON T0.DocEntry = T1.DocEntry WHERE T0.DocDate >= :fromDate"
}

{
  "SqlCode": "purch_lines_all",
  "SqlName": "Barcha xaridlar qatorlari bilan",
  "SqlText": "SELECT T0.DocNum, T0.DocDate, T0.CardCode, T1.ItemCode, T1.Quantity, T1.Price FROM OPCH T0 INNER JOIN PCH1 T1 ON T0.DocEntry = T1.DocEntry"
}

{
  "SqlCode": "pm_by_supplier",
  "SqlName": "Exact values of one purchase",
  "SqlText": "select T0.DocNum, T1.ItemCode, T1.Quantity, T1.Price, T1.LineTotal from OPCH T0 inner join PCH1 T1 on T0.DocEntry = T1.DocEntry where T0.CardCode = :cardCode"
}

{
  "SqlCode": "pm_alias",
  "SqlName": "Letters and aliases",
  "SqlText": "select t0.docnum as Num, COUNT(*) as Lines from opch t0 inner join pch1 t1 on t0.docentry = t1.docentry group by t0.docnum order by Num"
}

